class Check { [STAThread] static int Main(){var l=Layout.Default();if(!l.Add("autoloop")||l.Add("autoloop"))return 1;var c=l.Cards.Last();if(!WidgetGrid.Small(c))return 2;c.AutoloopMode="strip";var draft=LayoutEditSession.Clone(l);if(draft.Cards.Last().AutoloopMode!="strip"||WidgetGrid.Small(draft.Cards.Last()))return 3;using(var m=new MemoryStream()){new XmlSerializer(typeof(Layout)).Serialize(m,draft);m.Position=0;var restored=(Layout)new XmlSerializer(typeof(Layout)).Deserialize(m);restored.Normalize();if(restored.Cards.Last().AutoloopMode!="strip")return 4;restored.Cards.Last().AutoloopMode="invalid";restored.Normalize();if(restored.Cards.Last().AutoloopMode!="square")return 5;}if(!l.Remove("autoloop"))return 6;Console.WriteLine("Autoloop add, duplicate, grid modes, edit clone, XML round-trip, normalization, remove: passed");return 0;} }
